const crypto = require('crypto');
const body = JSON.stringify($input.first().json.body ?? {});
const headerSig = $input.first().json.headers['x-tts-signature'] || '';
const secret = $env.TIKTOK_APP_SECRET;
const computed = crypto.createHmac('sha256', secret).update(body).digest('hex');
if (computed !== headerSig) {
  throw new Error('TikTok webhook signature mismatch - possible spoofed request');
}
return [{ json: $input.first().json.body }];

const orderId = $json.data?.order_id || $json.order_id;
if (!orderId) throw new Error('No order_id in TikTok webhook payload');
return [{ json: { orderId } }];

const crypto = require('crypto');
const appKey = $env.TIKTOK_APP_KEY;
const appSecret = $env.TIKTOK_APP_SECRET;
const accessToken = $env.TIKTOK_ACCESS_TOKEN;
const shopCipher = $env.TIKTOK_SHOP_CIPHER;
const timestamp = Math.floor(Date.now() / 1000).toString();
const path = '/order/202309/orders';

const params = {
  app_key: appKey,
  shop_cipher: shopCipher,
  timestamp
};

// TikTok signing: sort params by key, concat key+value, wrap with path + app_secret, HMAC-SHA256
const sortedKeys = Object.keys(params).sort();
let base = path;
for (const key of sortedKeys) {
  base += key + params[key];
}
base = appSecret + base + appSecret;
const sign = crypto.createHmac('sha256', appSecret).update(base).digest('hex');

return [{
  json: {
    orderId: $json.orderId,
    path,
    queryParams: { ...params, sign, access_token: accessToken },
    body: { order_id_list: [$json.orderId] }
  }
}];

const order = ($json.data?.order_list || $json.data?.orders || [])[0] || {};
const recipient = order.recipient_address || {};
const items = order.line_items || order.item_list || [];
const productNames = items.map(i => i.product_name || i.sku_name).filter(Boolean).join(', ');
const qty = items.reduce((sum, i) => sum + (i.quantity || 1), 0);
return [{
  json: {
    date: new Date().toISOString(),
    orderId: order.order_id || order.id,
    product: productNames || '(unknown)',
    qty,
    amountRM: order.payment?.total_amount || order.payment_info?.total_amount || '',
    buyer: recipient.name || order.buyer_email || 'Unknown',
    phone: recipient.phone_number || '',
    address: [recipient.full_address, recipient.district, recipient.state].filter(Boolean).join(', '),
    status: order.status || order.order_status
  }
}];
